cuda_source = r'''
#include <torch/extension.h>
#include <cuda.h>
#include <cuda_runtime.h>
#include <cuda_fp16.h>

template <int BLOCK_SIZE>
__global__ void argmax_fp16_kernel(
    const __half* __restrict__ input,
          int64_t* __restrict__ output,
    const int outer,
    const int dim_size,
    const int inner)
{
    // One thread per (outer, inner) pair => reduces over dim_size
    const int idx = blockIdx.x * BLOCK_SIZE + threadIdx.x;
    const int total = outer * inner;
    if (idx >= total) return;

    const int outer_idx = idx / inner;   // which outer slice
    const int inner_idx = idx % inner;   // position inside inner slice

    // Pointer to the first element of this slice
    const __half* slice = input + outer_idx * dim_size * inner + inner_idx;

    // Initialize max with the smallest half value
    __half max_val = __float2half(-65504.0f);   // -inf for fp16
    int   max_idx = 0;

    // Stride between consecutive elements along the reduction dimension
    const int stride = inner;

    #pragma unroll
    for (int k = 0; k < dim_size; ++k) {
        __half val = slice[k * stride];
        // __hlt returns true if a < b
        if (__hlt(max_val, val)) {
            max_val = val;
            max_idx = k;
        }
    }

    output[idx] = static_cast<int64_t>(max_idx);
}

// Launcher (C++ bridge)
void argmax_fp16_launcher(
    torch::Tensor input,
    torch::Tensor output,
    const int dim)
{
    // Input must be contiguous half, output long
    TORCH_CHECK(input.is_contiguous(), "input must be contiguous");
    TORCH_CHECK(output.is_contiguous(), "output must be contiguous");
    TORCH_CHECK(input.dtype() == torch::kHalf, "input must be fp16");
    TORCH_CHECK(output.dtype() == torch::kLong, "output must be int64");

    const int64_t total_elems = input.numel();
    const int ndim = input.dim();

    // Compute outer, dim_size, inner based on dim
    int outer = 1;
    for (int i = 0; i < dim; ++i) outer *= input.size(i);
    int dim_size = input.size(dim);
    int inner = 1;
    for (int i = dim + 1; i < ndim; ++i) inner *= input.size(i);

    const int threads = 256;
    const int blocks = (outer * inner + threads - 1) / threads;

    const dim3 grid(blocks);
    const dim3 block(threads);

    // Get raw pointers
    const __half* in_ptr = reinterpret_cast<const __half*>(input.data_ptr<at::Half>());
    int64_t* out_ptr = output.data_ptr<int64_t>();

    // Launch kernel
    argmax_fp16_kernel<threads><<<grid, block, 0, at::cuda::getCurrentCUDAStream()>>>(
        in_ptr, out_ptr, outer, dim_size, inner
    );

    // Check for launch errors
    cudaError_t err = cudaGetLastError();
    if (err != cudaSuccess) {
        AT_ERROR("CUDA kernel launch failed: ", cudaGetErrorString(err));
    }
}
PYBIND11_MODULE(TORCH_EXTENSION_NAME, m) {
    m.def("argmax_fp16_launcher", &argmax_fp16_launcher, "Argmax over a dimension (fp16 input)");
}
'''

# ----------------------------------------------------------------------
# Compile the extension inline
# ----------------------------------------------------------------------
extension = load_inline(name='argmax_fp16_ext',
                        cpp_sources='',
                        cuda_sources=cuda_source,
                        functions=['argmax_fp16_launcher'],
                        verbose=False)

# ----------------------------------------------------------------------
# ModelNew definition using the custom kernel
# ----------------------------------------------------------------------
class ModelNew(nn.Module):
    """
    Drop‑in replacement for the reference Model that uses a custom CUDA kernel
    to compute argmax over a specified dimension on fp16 tensors.
    """
    def __init__(self, dim: int):
        super().__init__()
        self.dim = dim

    def forward(self, x: torch.Tensor) -> torch.Tensor:
        # Ensure input is fp16 and on CUDA
        if not x.is_cuda:
            x = x.cuda()
        x = x.to(torch.float16).contiguous()

        # Prepare output shape (dim removed)
        out_shape = list(x.shape)
        del out_shape[self.dim]
        out = torch.empty(out_shape, dtype=torch.long, device=x.device)

        # Call the compiled CUDA kernel
        extension.argmax_fp16_launcher(x, out, self.dim)

        return out

# ----------------------------------------------------------------------
# Helper functions matching the reference script
# ----------------------------------------------------------------------
batch_size = 128
dim1 = 4096
dim2 = 4095

def get_inputs():
    x = torch.rand(batch_size, dim1, dim2, dtype=torch.float16, device='cuda')
    return [x]

def get_init_inputs():
    # The reference init returns a list containing the dim (int)
    return [1]   # example: argmax over dimension 1
